package com.example.musicfilemanager

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.musicfilemanager.navigation.Routes
import com.example.musicfilemanager.ui.MainScreen
import com.example.musicfilemanager.ui.MusicDetailScreen
import com.example.musicfilemanager.ui.AddMusicScreen
import com.example.musicfilemanager.ui.OldMusicScreen
import com.example.musicfilemanager.ui.genres.AddGenreScreen
import com.example.musicfilemanager.ui.genres.GenreListScreen
import com.example.musicfilemanager.ui.genres.GenreUi
import com.example.musicfilemanager.ui.genres.GenreIcon
import com.example.musicfilemanager.ui.stats.StatsScreen
import com.example.musicfilemanager.ui.theme.AppTheme
import com.example.musicfilemanager.viewmodel.GenreViewModel

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            AppTheme {
                val nav = rememberNavController()
                NavHost(navController = nav, startDestination = Routes.Library) {
                    composable(Routes.Library) {
                        MainScreen(
                            onAddClick = { nav.navigate(Routes.AddMusic) },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "genre" -> nav.navigate(Routes.Genres)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }},
                            onItemClick = { id -> nav.navigate("detail/$id") },
                            onEditClick = { id -> 
                                // Navigate đến màn chỉnh sửa
                                nav.navigate(Routes.editMusic(id))
                            },
                            onDeleteClick = { id ->
                                // TODO: Hiển thị dialog xác nhận xóa
                                // Sau khi xóa, reload danh sách
                            }
                        )
                    }
                    composable(Routes.AddMusic) {
                        AddMusicScreen(
                            musicId = null, // null = chế độ thêm mới
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    // Route cho chỉnh sửa
                    composable(
                        route = Routes.EditMusic,
                        arguments = listOf(navArgument("id"){ defaultValue = "1" })
                    ) { backStack ->
                        val id = backStack.arguments?.getString("id") ?: "1"
                        AddMusicScreen(
                            musicId = id, // truyền id để chỉnh sửa
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    composable(Routes.Genres) {
                        GenreListScreen(
                            onAdd = { nav.navigate(Routes.AddGenre) },
                            onEdit = { id -> nav.navigate(Routes.editGenre(id)) },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "library" -> nav.navigate(Routes.Library)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }}
                        ) 
                    }
                    composable(Routes.AddGenre) { AddGenreScreen(onBack = { nav.popBackStack() }, onSaved = { nav.popBackStack() }) }
                    // Route cho chỉnh sửa Genre
                    composable(
                        route = Routes.EditGenre,
                        arguments = listOf(navArgument("id"){ defaultValue = "" })
                    ) { backStack ->
                        val genreViewModel: GenreViewModel = viewModel()
                        val id = backStack.arguments?.getString("id") ?: ""

                        // Lấy thông tin genre từ ViewModel với API ID
                        val genreWithId = genreViewModel.getGenreWithIdByCode(id)
                        val genreToEdit = genreWithId?.let {
                            GenreUi(
                                id = it.genre.id,
                                apiId = it.apiId,
                                name = it.genre.name,
                                description = it.description ?: "Thể loại ${it.genre.name}",
                                ageRange = it.ageRange,
                                fileCount = it.totalFiles,
                                icon = when (it.genre.id.lowercase()) {
                                    "rock" -> GenreIcon.Rock
                                    "pop" -> GenreIcon.Pop
                                    "jazz" -> GenreIcon.Jazz
                                    "hiphop", "hip hop" -> GenreIcon.HipHop
                                    else -> GenreIcon.Pop
                                }
                            )
                        }

                        AddGenreScreen(
                            genreToEdit = genreToEdit,
                            viewModel = genreViewModel,
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    composable(Routes.Stats) {
                        StatsScreen(
                            onBack = { nav.popBackStack() },
                            onBottomItemClick = { when (it) {
                                "library" -> nav.navigate(Routes.Library)
                                "genre" -> nav.navigate(Routes.Genres)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }}
                        )
                    }
                    composable(Routes.OldMusic) {
                        OldMusicScreen(
                            onBack = { nav.popBackStack() },
                            onItemClick = { id -> nav.navigate(Routes.detail(id)) },
                            onEditClick = { id -> nav.navigate(Routes.editMusic(id)) },
                            onDeleteClick = { id ->
                                // TODO: Xóa nhạc
                            },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "library" -> nav.navigate(Routes.Library)
                                "genre" -> nav.navigate(Routes.Genres)
                                else -> {}
                            }}
                        )
                    }
                    composable(
                        route = Routes.Detail,
                        arguments = listOf(navArgument("id"){ defaultValue = "1" })
                    ) { backStack ->
                        val id = backStack.arguments?.getString("id") ?: "1"
                        MusicDetailScreen(
                            musicId = id,
                            onBack = { nav.popBackStack() },
                            onEdit = { /* nav to AddMusic with id if you reuse form */ },
                            onDelete = { nav.popBackStack() }
                        )
                    }
                }
            }
        }

    }
}

package com.example.musicfilemanager

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.musicfilemanager.navigation.Routes
import com.example.musicfilemanager.ui.MainScreen
import com.example.musicfilemanager.ui.MusicDetailScreen
import com.example.musicfilemanager.ui.AddMusicScreen
import com.example.musicfilemanager.ui.OldMusicScreen
import com.example.musicfilemanager.ui.components.DeleteConfirmDialog
import com.example.musicfilemanager.ui.genres.AddGenreScreen
import com.example.musicfilemanager.ui.genres.GenreListScreen
import com.example.musicfilemanager.ui.genres.GenreUi
import com.example.musicfilemanager.ui.genres.GenreIcon
import com.example.musicfilemanager.ui.stats.StatsScreen
import com.example.musicfilemanager.ui.theme.AppTheme
import com.example.musicfilemanager.viewmodel.GenreViewModel
import com.example.musicfilemanager.viewmodel.MusicViewModel

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContent {
            AppTheme {
                val nav = rememberNavController()
                NavHost(navController = nav, startDestination = Routes.Library) {
                    composable(Routes.Library) {
                        val musicViewModel: MusicViewModel = viewModel()

                        // State for delete confirmation dialog
                        var showDeleteDialog by remember { mutableStateOf(false) }
                        var musicToDelete by remember { mutableStateOf<Pair<Int, String>?>(null) } // apiId, title

                        MainScreen(
                            musicViewModel = musicViewModel,
                            onAddClick = { nav.navigate(Routes.AddMusic) },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "genre" -> nav.navigate(Routes.Genres)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }},
                            onItemClick = { id -> nav.navigate("detail/$id") },
                            onEditClick = { id -> 
                                // Navigate đến màn chỉnh sửa
                                nav.navigate(Routes.editMusic(id))
                            },
                            onDeleteClick = { apiId, title ->
                                // Hiển thị dialog xác nhận xóa
                                musicToDelete = Pair(apiId, title)
                                showDeleteDialog = true
                            }
                        )

                        // Delete confirmation dialog
                        if (showDeleteDialog && musicToDelete != null) {
                            DeleteConfirmDialog(
                                fileName = musicToDelete!!.second,
                                onConfirm = {
                                    // Gọi API xóa
                                    musicViewModel.deleteMusicFile(
                                        id = musicToDelete!!.first,
                                        fileName = musicToDelete!!.second
                                    )
                                    showDeleteDialog = false
                                    musicToDelete = null
                                },
                                onDismiss = {
                                    showDeleteDialog = false
                                    musicToDelete = null
                                }
                            )
                        }
                    }
                    composable(Routes.AddMusic) {
                        AddMusicScreen(
                            musicId = null, // null = chế độ thêm mới
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    // Route cho chỉnh sửa
                    composable(
                        route = Routes.EditMusic,
                        arguments = listOf(navArgument("id"){ defaultValue = "1" })
                    ) { backStack ->
                        val id = backStack.arguments?.getString("id") ?: "1"
                        AddMusicScreen(
                            musicId = id, // truyền id để chỉnh sửa
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    composable(Routes.Genres) {
                        GenreListScreen(
                            onAdd = { nav.navigate(Routes.AddGenre) },
                            onEdit = { id -> nav.navigate(Routes.editGenre(id)) },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "library" -> nav.navigate(Routes.Library)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }}
                        ) 
                    }
                    composable(Routes.AddGenre) { AddGenreScreen(onBack = { nav.popBackStack() }, onSaved = { nav.popBackStack() }) }
                    // Route cho chỉnh sửa Genre
                    composable(
                        route = Routes.EditGenre,
                        arguments = listOf(navArgument("id"){ defaultValue = "" })
                    ) { backStack ->
                        val genreViewModel: GenreViewModel = viewModel()
                        val id = backStack.arguments?.getString("id") ?: ""

                        // Lấy thông tin genre từ ViewModel với API ID
                        val genreWithId = genreViewModel.getGenreWithIdByCode(id)
                        val genreToEdit = genreWithId?.let {
                            GenreUi(
                                id = it.genre.id,
                                apiId = it.apiId,
                                name = it.genre.name,
                                description = it.description ?: "Thể loại ${it.genre.name}",
                                ageRange = it.ageRange,
                                fileCount = it.totalFiles,
                                icon = when (it.genre.id.lowercase()) {
                                    "rock" -> GenreIcon.Rock
                                    "pop" -> GenreIcon.Pop
                                    "jazz" -> GenreIcon.Jazz
                                    "hiphop", "hip hop" -> GenreIcon.HipHop
                                    else -> GenreIcon.Pop
                                }
                            )
                        }

                        AddGenreScreen(
                            genreToEdit = genreToEdit,
                            viewModel = genreViewModel,
                            onBack = { nav.popBackStack() },
                            onSaved = { nav.popBackStack() }
                        )
                    }
                    composable(Routes.Stats) {
                        StatsScreen(
                            onBack = { nav.popBackStack() },
                            onBottomItemClick = { when (it) {
                                "library" -> nav.navigate(Routes.Library)
                                "genre" -> nav.navigate(Routes.Genres)
                                "oldmusic" -> nav.navigate(Routes.OldMusic)
                                else -> {}
                            }}
                        )
                    }
                    composable(Routes.OldMusic) {
                        OldMusicScreen(
                            onBack = { nav.popBackStack() },
                            onItemClick = { id -> nav.navigate(Routes.detail(id)) },
                            onEditClick = { id -> nav.navigate(Routes.editMusic(id)) },
                            onDeleteClick = { id ->
                                // TODO: Xóa nhạc
                            },
                            onBottomItemClick = { when (it) {
                                "home" -> nav.navigate(Routes.Stats)
                                "library" -> nav.navigate(Routes.Library)
                                "genre" -> nav.navigate(Routes.Genres)
                                else -> {}
                            }}
                        )
                    }
                    composable(
                        route = Routes.Detail,
                        arguments = listOf(navArgument("id"){ defaultValue = "1" })
                    ) { backStack ->
                        val id = backStack.arguments?.getString("id") ?: "1"
                        MusicDetailScreen(
                            musicId = id,
                            onBack = { nav.popBackStack() },
                            onEdit = { /* nav to AddMusic with id if you reuse form */ },
                            onDelete = { nav.popBackStack() }
                        )
                    }
                }
            }
        }

    }
}

package com.example.musicfilemanager.api

import com.example.musicfilemanager.api.models.MusicFileRequest
import com.example.musicfilemanager.api.models.MusicFileResponse
import com.example.musicfilemanager.api.models.PagedResponse
import retrofit2.Response
import retrofit2.http.*

/**
 * Retrofit API service for Music Files endpoints
 * Base URL: http://10.0.2.2:3005/api
 */
interface MusicApiService {

    /**
     * Get all music files with pagination
     * GET /api/music-files?page=0&size=20&sort=createdAt,desc
     */
    @GET("music-files")
    suspend fun getAllMusicFiles(
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100,
        @Query("sort") sort: String = "createdAt,desc"
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Get music file by ID
     * GET /api/music-files/{id}
     */
    @GET("music-files/{id}")
    suspend fun getMusicFileById(@Path("id") id: Int): Response<MusicFileResponse>

    /**
     * Get music file by code
     * GET /api/music-files/code/{code}
     */
    @GET("music-files/code/{code}")
    suspend fun getMusicFileByCode(@Path("code") code: String): Response<MusicFileResponse>

    /**
     * Search music files by keyword
     * GET /api/music-files/search?keyword={keyword}&page=0&size=20
     */
    @GET("music-files/search")
    suspend fun searchMusicFiles(
        @Query("keyword") keyword: String,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Filter music files by genre
     * GET /api/music-files/filter/genre/{genreId}
     */
    @GET("music-files/filter/genre/{genreId}")
    suspend fun filterByGenre(
        @Path("genreId") genreId: Int,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Filter music files by year
     * GET /api/music-files/filter/year/{year}
     */
    @GET("music-files/filter/year/{year}")
    suspend fun filterByYear(
        @Path("year") year: Int,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Create new music file
     * POST /api/music-files
     */
    @POST("music-files")
    suspend fun createMusicFile(@Body request: MusicFileRequest): Response<MusicFileResponse>

    /**
     * Update music file
     * PUT /api/music-files/{id}
     */
    @PUT("music-files/{id}")
    suspend fun updateMusicFile(
        @Path("id") id: Int,
        @Body request: MusicFileRequest
    ): Response<MusicFileResponse>

    /**
     * Delete music file
     * DELETE /api/music-files/{id}
     */
    @DELETE("music-files/{id}")
    suspend fun deleteMusicFile(@Path("id") id: Int): Response<Unit>

    /**
     * Upload music file (step 1)
     * POST /api/music-files/upload
     * Returns: { id, fileCode, fileName, filePath, downloadLink, ... }
     */
    @Multipart
    @POST("music-files/upload")
    suspend fun uploadMusicFile(
        @Part file: okhttp3.MultipartBody.Part,
        @Part("fileCode") fileCode: okhttp3.RequestBody,
        @Part("fileName") fileName: okhttp3.RequestBody
    ): Response<MusicFileResponse>

    /**
     * Get statistics
     * GET /api/music-files/stats/summary
     */
    @GET("music-files/stats/summary")
    suspend fun getStatistics(): Response<Map<String, Any>>
}

package com.example.musicfilemanager.api

import com.example.musicfilemanager.api.models.MusicFileRequest
import com.example.musicfilemanager.api.models.MusicFileResponse
import com.example.musicfilemanager.api.models.PagedResponse
import retrofit2.Response
import retrofit2.http.*

/**
 * Retrofit API service for Music Files endpoints
 * Base URL: http://10.0.2.2:3005/api
 */
interface MusicApiService {

    /**
     * Get all music files with pagination
     * GET /api/music-files?page=0&size=20&sort=createdAt,desc
     */
    @GET("music-files")
    suspend fun getAllMusicFiles(
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100,
        @Query("sort") sort: String = "createdAt,desc"
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Get music file by ID
     * GET /api/music-files/{id}
     */
    @GET("music-files/{id}")
    suspend fun getMusicFileById(@Path("id") id: Int): Response<MusicFileResponse>

    /**
     * Get music file by code
     * GET /api/music-files/code/{code}
     */
    @GET("music-files/code/{code}")
    suspend fun getMusicFileByCode(@Path("code") code: String): Response<MusicFileResponse>

    /**
     * Search music files by keyword
     * GET /api/music-files/search?keyword={keyword}&page=0&size=20
     */
    @GET("music-files/search")
    suspend fun searchMusicFiles(
        @Query("keyword") keyword: String,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Filter music files by genre
     * GET /api/music-files/filter/genre/{genreId}
     */
    @GET("music-files/filter/genre/{genreId}")
    suspend fun filterByGenre(
        @Path("genreId") genreId: Int,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Filter music files by year
     * GET /api/music-files/filter/year/{year}
     */
    @GET("music-files/filter/year/{year}")
    suspend fun filterByYear(
        @Path("year") year: Int,
        @Query("page") page: Int = 0,
        @Query("size") size: Int = 100
    ): Response<PagedResponse<MusicFileResponse>>

    /**
     * Create new music file
     * POST /api/music-files
     */
    @POST("music-files")
    suspend fun createMusicFile(@Body request: MusicFileRequest): Response<MusicFileResponse>

    /**
     * Update music file
     * PUT /api/music-files/{id}
     */
    @PUT("music-files/{id}")
    suspend fun updateMusicFile(
        @Path("id") id: Int,
        @Body request: MusicFileRequest
    ): Response<MusicFileResponse>

    /**
     * Delete music file
     * DELETE /api/music-files/{id}
     */
    @DELETE("music-files/{id}")
    suspend fun deleteMusicFile(@Path("id") id: Int): Response<Unit>

    /**
     * Upload music file (step 1)
     * POST /api/music-files/upload
     * Gửi fileCode tạm (server required), nhưng server sẽ trả về fileCode chính thức
     * Returns: { id, fileCode, fileName, filePath, downloadLink, ... }
     */
    @Multipart
    @POST("music-files/upload")
    suspend fun uploadMusicFile(
        @Part file: okhttp3.MultipartBody.Part,
        @Part("fileCode") fileCode: okhttp3.RequestBody,
        @Part("fileName") fileName: okhttp3.RequestBody
    ): Response<MusicFileResponse>

    /**
     * Get statistics
     * GET /api/music-files/stats/summary
     */
    @GET("music-files/stats/summary")
    suspend fun getStatistics(): Response<Map<String, Any>>
}

package com.example.musicfilemanager.data

import com.example.musicfilemanager.api.ApiClient
import com.example.musicfilemanager.api.ApiResult
import com.example.musicfilemanager.api.models.MusicFileRequest
import com.example.musicfilemanager.api.models.MusicFileResponse
import com.example.musicfilemanager.api.safeApiCall
import com.example.musicfilemanager.model.Music
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import okhttp3.MediaType.Companion.toMediaTypeOrNull
import okhttp3.RequestBody.Companion.asRequestBody
import okhttp3.RequestBody.Companion.toRequestBody

/**
 * Data class to hold Music File with API ID
 */
data class MusicFileWithId(
    val apiId: Int,
    val music: Music,
    val fileCode: String,
    val filePath: String? = null,
    val thumbnailPath: String? = null,
    val fileType: String? = null,
    val downloadLink: String? = null,
    val description: String? = null,
    val fileSize: Long? = null,
    val createdAt: String? = null,
    val updatedAt: String? = null
)

/**
 * Repository for Music Files API
 * Kết hợp với cache local để tăng performance
 */
object MusicApiRepository {

    private val apiService = ApiClient.musicService

    // Cache local
    private val _musicFiles = MutableStateFlow<List<Music>>(emptyList())
    val musicFiles: StateFlow<List<Music>> = _musicFiles.asStateFlow()

    // Cache with API IDs
    private val _musicFilesWithId = MutableStateFlow<List<MusicFileWithId>>(emptyList())
    val musicFilesWithId: StateFlow<List<MusicFileWithId>> = _musicFilesWithId.asStateFlow()

    // Loading state
    private val _isLoading = MutableStateFlow(false)
    val isLoading: StateFlow<Boolean> = _isLoading.asStateFlow()

    // Error state
    private val _error = MutableStateFlow<String?>(null)
    val error: StateFlow<String?> = _error.asStateFlow()

    /**
     * Fetch all music files from API
     */
    suspend fun fetchAllMusicFiles(): ApiResult<List<Music>> {
        _isLoading.value = true
        _error.value = null

        val result = safeApiCall { apiService.getAllMusicFiles(page = 0, size = 100) }

        when (result) {
            is ApiResult.Success -> {
                // Convert API response to domain model with IDs
                val musicFileWithIdList = result.data.content.map { response ->
                    MusicFileWithId(
                        apiId = response.id,
                        music = response.toMusic(),
                        fileCode = response.fileCode,
                        filePath = response.filePath,
                        thumbnailPath = response.thumbnailPath,
                        fileType = response.fileType,
                        downloadLink = response.downloadLink,
                        description = response.description,
                        fileSize = response.fileSize,
                        createdAt = response.createdAt,
                        updatedAt = response.updatedAt
                    )
                }

                // Store full list with IDs
                _musicFilesWithId.value = musicFileWithIdList

                // Extract music for normal use
                _musicFiles.value = musicFileWithIdList.map { it.music }

                _isLoading.value = false
                return ApiResult.Success(_musicFiles.value)
            }
            is ApiResult.Error -> {
                _error.value = result.message
                _isLoading.value = false
                return result
            }
            is ApiResult.Loading -> {
                return result
            }
        }
    }

    /**
     * Search music files by keyword
     */
    suspend fun searchMusicFiles(keyword: String): ApiResult<List<Music>> {
        _isLoading.value = true
        _error.value = null

        val result = safeApiCall { apiService.searchMusicFiles(keyword) }
        _isLoading.value = false

        return when (result) {
            is ApiResult.Success -> {
                val musicList = result.data.content.map { it.toMusic() }
                ApiResult.Success(musicList)
            }
            is ApiResult.Error -> {
                _error.value = result.message
                result
            }
            is ApiResult.Loading -> result
        }
    }

    /**
     * Filter music files by genre
     */
    suspend fun filterByGenre(genreId: Int): ApiResult<List<Music>> {
        _isLoading.value = true
        _error.value = null

        val result = safeApiCall { apiService.filterByGenre(genreId) }
        _isLoading.value = false

        return when (result) {
            is ApiResult.Success -> {
                val musicList = result.data.content.map { it.toMusic() }
                ApiResult.Success(musicList)
            }
            is ApiResult.Error -> {
                _error.value = result.message
                result
            }
