                    modifier = Modifier.size(20.dp)
                )
            }
        }
    }
}

@Composable
private fun BottomNavBar(current: String, onClick: (String) -> Unit) {
    NavigationBar(containerColor = Gray800) {
        val items = listOf(
            "home" to Icons.Outlined.Home,
            "library" to Icons.Outlined.MenuBook,
            "genre" to Icons.Outlined.Category,
            "oldmusic" to Icons.Outlined.MusicNote // Đổi từ settings → oldmusic
        )
        items.forEach { (id, icon) ->
            NavigationBarItem(
                selected = id == current,
                onClick = { onClick(id) },
                icon = {
                    Box(
                        Modifier
                            .size(26.dp)
                            .clip(CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(icon, null)
                    }
                },
                label = {
                    Text(
                        when (id) {
                            "home" -> "Trang chủ"
                            "library" -> "Thư viện"
                            "genre" -> "Thể loại"
                            "oldmusic" -> "Nhạc cũ"
                            else -> "Khác"
                        }
                    )
                },
                colors = NavigationBarItemDefaults.colors(
                    selectedIconColor = AccentPurple,
                    selectedTextColor = AccentPurple,
                    indicatorColor = Gray700,
                    unselectedIconColor = TextSecondary,
                    unselectedTextColor = TextSecondary
                )
            )
        }
    }
}

package com.example.musicfilemanager.ui.components

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.outlined.Warning
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.unit.dp
import androidx.compose.ui.window.Dialog
import com.example.musicfilemanager.ui.theme.Gray800
import com.example.musicfilemanager.ui.theme.Gray900
import com.example.musicfilemanager.ui.theme.TextPrimary
import com.example.musicfilemanager.ui.theme.TextSecondary

/**
 * Dialog xác nhận xóa file nhạc
 */
@Composable
fun DeleteConfirmDialog(
    fileName: String,
    onConfirm: () -> Unit,
    onDismiss: () -> Unit
) {
    Dialog(onDismissRequest = onDismiss) {
        Surface(
            shape = RoundedCornerShape(20.dp),
            color = Gray800,
            tonalElevation = 8.dp
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // Warning Icon
                Box(
                    modifier = Modifier
                        .size(64.dp)
                        .background(
                            Color(0x20EF5350),
                            RoundedCornerShape(32.dp)
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        Icons.Outlined.Warning,
                        contentDescription = null,
                        tint = Color(0xFFEF5350),
                        modifier = Modifier.size(32.dp)
                    )
                }

                Spacer(Modifier.height(16.dp))

                // Title
                Text(
                    text = "Xác nhận xóa",
                    style = MaterialTheme.typography.titleLarge.copy(
                        fontWeight = FontWeight.Bold
                    ),
                    color = TextPrimary
                )

                Spacer(Modifier.height(8.dp))

                // Message
                Text(
                    text = "Bạn có chắc chắn muốn xóa file nhạc này?",
                    style = MaterialTheme.typography.bodyMedium,
                    color = TextSecondary,
                    textAlign = TextAlign.Center
                )

                Spacer(Modifier.height(4.dp))

                // File name
                Text(
                    text = "\"$fileName\"",
                    style = MaterialTheme.typography.bodyMedium.copy(
                        fontWeight = FontWeight.SemiBold
                    ),
                    color = TextPrimary,
                    textAlign = TextAlign.Center
                )

                Spacer(Modifier.height(24.dp))

                // Buttons
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    // Cancel Button
                    OutlinedButton(
                        onClick = onDismiss,
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.outlinedButtonColors(
                            contentColor = TextSecondary
                        )
                    ) {
                        Text("Hủy")
                    }

                    // Delete Button
                    Button(
                        onClick = onConfirm,
                        modifier = Modifier.weight(1f),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = Color(0xFFEF5350)
                        )
                    ) {
                        Text("Xóa", color = Color.White)
                    }
                }
            }
        }
    }
}

package com.example.musicfilemanager.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.musicfilemanager.api.ApiResult
import com.example.musicfilemanager.data.GenreApiRepository
import com.example.musicfilemanager.model.Genre
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * ViewModel for Genre screen
 * Manages UI state and business logic
 */
class GenreViewModel : ViewModel() {

    private val repository = GenreApiRepository

    // UI States
    val genres: StateFlow<List<Genre>> = repository.genres
    val genresWithId = repository.genresWithId
    val isLoading: StateFlow<Boolean> = repository.isLoading
    val error: StateFlow<String?> = repository.error

    // Selected genre for editing
    private val _selectedGenre = MutableStateFlow<Genre?>(null)
    val selectedGenre: StateFlow<Genre?> = _selectedGenre.asStateFlow()

    // Success message
    private val _successMessage = MutableStateFlow<String?>(null)
    val successMessage: StateFlow<String?> = _successMessage.asStateFlow()

    init {
        // Load genres when ViewModel is created
        loadGenres()
    }

    /**
     * Load all genres from API
     */
    fun loadGenres() {
        viewModelScope.launch {
            repository.fetchAllGenres()
        }
    }

    /**
     * Create new genre
     */
    fun createGenre(
        code: String,
        name: String,
        description: String? = null,
        ageRange: String? = null
    ) {
        viewModelScope.launch {
            val result = repository.createGenre(code, name, description, ageRange)
            when (result) {
                is ApiResult.Success -> {
                    _successMessage.value = "Thêm thể loại '$name' thành công!"
                }
                is ApiResult.Error -> {
                    // Error is already set in repository
                }
                is ApiResult.Loading -> {}
            }
        }
    }

    /**
     * Update existing genre
     */
    fun updateGenre(
        id: Int,
        code: String,
        name: String,
        description: String? = null,
        ageRange: String? = null
    ) {
        viewModelScope.launch {
            val result = repository.updateGenre(id, code, name, description, ageRange)
            when (result) {
                is ApiResult.Success -> {
                    _successMessage.value = "Cập nhật thể loại '$name' thành công!"
                    _selectedGenre.value = null
                }
                is ApiResult.Error -> {
                    // Error is already set in repository
                }
                is ApiResult.Loading -> {}
            }
        }
    }

    /**
     * Delete genre
     */
    fun deleteGenre(id: Int, name: String) {
        viewModelScope.launch {
            val result = repository.deleteGenre(id)
            when (result) {
                is ApiResult.Success -> {
                    _successMessage.value = "Xóa thể loại '$name' thành công!"
                }
                is ApiResult.Error -> {
                    // Error is already set in repository
                }
                is ApiResult.Loading -> {}
            }
        }
    }

    /**
     * Select genre for editing
     */
    fun selectGenre(genre: Genre) {
        _selectedGenre.value = genre
    }

    /**
     * Clear selected genre
     */
    fun clearSelectedGenre() {
        _selectedGenre.value = null
    }

    /**
     * Clear success message
     */
    fun clearSuccessMessage() {
        _successMessage.value = null
    }

    /**
     * Clear error message
     */
    fun clearError() {
        repository.clearError()
    }

    /**
     * Get genres without "Tất cả"
     */
    fun getGenresWithoutAll(): List<Genre> {
        return repository.getGenresWithoutAll()
    }

    /**
     * Get GenreWithId by code for edit/delete
     */
    fun getGenreWithIdByCode(code: String) = repository.getGenreWithIdByCode(code)

    /**
     * Map API genreId (Int) to UI genreCode (String)
     * Lookup từ genres đã load từ API
     */
    fun mapGenreIdToCode(apiGenreId: Int): String {
        val genreWithId = genresWithId.value.find { it.apiId == apiGenreId }
        return genreWithId?.code ?: "pop" // fallback to "pop" if not found
    }
}

